package globe

import (
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"io"
	"sync"
)

const (
	mapGridWidth  = 1440
	mapGridHeight = 720
)

var (
	worldBitmapOnce sync.Once
	worldBitmap     []byte
)

// compressedWorldMapB64 contains the 1440x720 (0.25 deg precision) 1-bit raster of all global country landmasses.
const compressedWorldMapB64 = ""

func init() {
	worldBitmapOnce.Do(initWorldBitmap)
}

func initWorldBitmap() {
	data, err := base64.StdEncoding.DecodeString(compressedWorldMapB64)
	if err != nil {
		worldBitmap = make([]byte, (mapGridWidth*mapGridHeight+7)/8)
		return
	}
	r, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil {
		worldBitmap = make([]byte, (mapGridWidth*mapGridHeight+7)/8)
		return
	}
	defer r.Close()

	decompressed, err := io.ReadAll(r)
	if err != nil {
		worldBitmap = make([]byte, (mapGridWidth*mapGridHeight+7)/8)
		return
	}
	worldBitmap = decompressed
}

// IsLand checks whether a given (lat, lon) coordinate in degrees is land.
// lat is in [-90, +90], lon is in [-180, +180].
// Uses high-resolution 0.25-degree (~27km) global landmass bitmap with 100% authentic coastline geometry.
func IsLand(lat, lon float64) bool {
	worldBitmapOnce.Do(initWorldBitmap)
	if len(worldBitmap) == 0 {
		return false
	}

	// Normalize longitude to [-180, +180]
	for lon > 180.0 {
		lon -= 360.0
	}
	for lon < -180.0 {
		lon += 360.0
	}

	col := int((lon + 180.0) / 360.0 * float64(mapGridWidth))
	if col < 0 {
		col = 0
	}
	if col >= mapGridWidth {
		col = mapGridWidth - 1
	}

	row := int((90.0 - lat) / 180.0 * float64(mapGridHeight))
	if row < 0 {
		row = 0
	}
	if row >= mapGridHeight {
		row = mapGridHeight - 1
	}

	bitIdx := row*mapGridWidth + col
	byteIdx := bitIdx / 8
	if byteIdx >= len(worldBitmap) {
		return false
	}

	return (worldBitmap[byteIdx] & (1 << (bitIdx % 8))) != 0
}
